/**
 * GBLegalityData.h - Game Boy (Gen I/II) legality tables.
 *
 * The definitions live in src/Legality/GBLegalityData.cpp, which is generated by
 * tools/gen_gb_legality_data.py from a pinned PKHeX checkout. Species and move ids
 * are National Dex / national move ids (all <= 251 for these games).
 */

#ifndef LEGALITY_GB_LEGALITY_DATA_H
#define LEGALITY_GB_LEGALITY_DATA_H

#include <cstddef>
#include <cstdint>

namespace Legality::GBData {

    // Version bits; Gen I and Gen II share one namespace so an encounter list can
    // carry either. "Green" is the Japanese release whose data matches Blue (INT).
    enum Version : uint8_t {
        Red = 0x01, Green = 0x02, BlueJP = 0x04, Yellow = 0x08,
        Gold = 0x10, Silver = 0x20, Crystal = 0x40,
        AnyGen1 = Red | Green | BlueJP | Yellow,
        AnyGen2 = Gold | Silver | Crystal,
    };

    enum class SlotType1 : uint8_t { Grass, Surf, OldRod, GoodRod, SuperRod };
    enum class SlotType2 : uint8_t {
        Grass, Surf, OldRod, GoodRod, SuperRod, RockSmash, Headbutt, HeadbuttSpecial, BugContest
    };

    // PKHeX EvolutionType values used by Gen I/II data.
    enum EvolutionMethod : uint8_t {
        EvoLevelUpFriendship = 1, EvoLevelUpFriendshipMorning = 2, EvoLevelUpFriendshipNight = 3,
        EvoLevelUp = 4, EvoTrade = 5, EvoTradeHeldItem = 6, EvoUseItem = 8,
        EvoLevelUpATK = 9, EvoLevelUpAeqD = 10, EvoLevelUpDEF = 11,
    };

    struct Personal1 {
        uint8_t stats[5];      // HP ATK DEF SPE SPC
        uint8_t types[2];
        uint8_t catchRate;
        uint8_t growth;
        uint8_t baseMoves[4];  // moves known at level 1
        uint8_t tmhm[7];       // TM01-TM50, HM01-HM05 bit flags
    };

    struct Personal2 {
        uint8_t stats[6];      // HP ATK DEF SPE SPA SPD
        uint8_t types[2];
        uint8_t catchRate;
        uint8_t growth;
        uint8_t genderRatio;   // 255 genderless, 254 female only, 0 male only
        uint8_t eggGroups;     // low nibble group 1, high nibble group 2
        uint8_t hatchCycles;
        uint8_t tmhm[8];       // TM01-TM50, HM01-HM07, then the three Crystal tutors
    };

    struct LevelMove { uint8_t level; uint8_t move; };

    struct Evolution {
        uint8_t from, to, method, level;
        uint16_t argument;
    };

    struct WildSlot {
        uint8_t species, minLevel, maxLevel, type, location, time, version;
    };

    struct Static1 { uint8_t species, level, version; };

    struct Trade1 {
        uint8_t species, version;
        uint8_t levelMinRBY;   // earliest level the requested Pokemon can be in R/B/Y
        uint8_t levelMinGSC;   // ... once Gen II can supply it through the Time Capsule
        uint8_t nameIndex;     // row in kTradeNames1
        bool evolveOnTrade;
    };

    // PKHeX event1.pkl: GB-era Gen I event distributions.
    struct Gift1 {
        uint8_t species, level;
        uint8_t moves[4];
        uint8_t language;      // 0 any, 1 Japanese, 2 international
        uint8_t trainer;       // 0 recipient, 1 VC Mew, 2 Stadium, 3 Europe tour, 4 Japan tour
    };

    struct Static2 {
        uint8_t species, level, version, location;
        bool egg, shinyAlways, shinyNever;
        uint8_t gender;        // 255 when not fixed
        uint8_t moves[4];      // all zero when the level-up moveset applies
        uint8_t dvs[6];        // HP ATK DEF SPE SPA SPD; 255 when not fixed
    };

    struct Trade2 {
        uint8_t species, level;
        uint16_t tid;
        uint8_t nameIndex, gender, otGender;
        uint8_t dvs[6];        // 255 when not fixed
    };

    // PKHeX event2.pkl: GB-era Gen II event distributions.
    struct Gift2 {
        uint8_t species, level;
        uint8_t moves[4];
        uint8_t location;
        uint8_t currentLevel;  // minimum level when received (0 = encounter level)
        uint8_t shiny;         // 1 = always shiny
        uint8_t egg;           // 1 = distributed as an egg
        uint8_t language;      // 0 international, 1 Japanese, 2 English, 3 international non-English
        uint8_t trainer;       // 0 recipient, 1-3 Stadium 2 (JPN/ENG/INT), 4 Pokemon Center New York
    };

    // Stadium 2 move reminder: a move can be relearned once the Pokemon reaches `level`
    // when any of the four level-up source bits (RB, YW, GS, C) is set.
    struct Stadium2Move { uint8_t level, move, sources; };

    struct TradeName { uint8_t language; uint8_t index; const char* name; };

    extern const Personal1 kPersonalRB[152];
    extern const Personal1 kPersonalY[152];
    extern const Personal2 kPersonalGS[252];
    extern const Personal2 kPersonalC[252];

    // Learnsets: kLevelUpXIndex[species] .. kLevelUpXIndex[species + 1] in kLevelUpX.
    extern const uint16_t kLevelUpRBIndex[153];
    extern const LevelMove kLevelUpRB[];
    extern const uint16_t kLevelUpYIndex[153];
    extern const LevelMove kLevelUpY[];
    extern const uint16_t kLevelUpGSIndex[253];
    extern const LevelMove kLevelUpGS[];
    extern const uint16_t kLevelUpCIndex[253];
    extern const LevelMove kLevelUpC[];
    extern const uint16_t kEggMovesGSIndex[253];
    extern const uint8_t kEggMovesGS[];
    extern const uint16_t kEggMovesCIndex[253];
    extern const uint8_t kEggMovesC[];

    extern const Evolution kEvolutions1[];
    extern const std::size_t kEvolutions1Count;
    extern const Evolution kEvolutions2[];
    extern const std::size_t kEvolutions2Count;

    extern const WildSlot kWildSlots[];
    extern const std::size_t kWildSlotCount;

    extern const Static1 kStatics1[];
    extern const std::size_t kStatics1Count;
    extern const Trade1 kTrades1[];
    extern const std::size_t kTrades1Count;
    extern const Gift1 kGifts1[];
    extern const std::size_t kGifts1Count;
    extern const Static2 kStatics2[];
    extern const std::size_t kStatics2Count;
    extern const Trade2 kTrades2[];
    extern const std::size_t kTrades2Count;

    extern const uint8_t kHeldItems2[32];   // bit set of Gen II item ids a Pokemon can hold
    extern const uint8_t kMovePP1[166];     // base PP per move id in Gen I
    extern const uint8_t kMovePP2[252];     // base PP per move id in Gen II (differs only for Struggle)
    extern const Gift2 kGifts2[];
    extern const std::size_t kGifts2Count;
    extern const uint16_t kStadium2RelearnIndex[253];
    extern const Stadium2Move kStadium2Relearn[];

    // Language ids follow PKHeX: 1 Japanese, 2 English, 3 French, 4 Italian,
    // 5 German, 7 Spanish, 8 Korean.
    extern const TradeName kTradeNames1[];
    extern const std::size_t kTradeNames1Count;
    extern const TradeName kTradeNames2[];
    extern const std::size_t kTradeNames2Count;

    // TM/HM move ids in machine order.
    inline constexpr uint8_t kMachineMoves1[55] = {
          5,  13,  14,  18,  25,  92,  32,  34,  36,  38,
         61,  55,  58,  59,  63,   6,  66,  68,  69,  99,
         72,  76,  82,  85,  87,  89,  90,  91,  94, 100,
        102, 104, 115, 117, 118, 120, 121, 126, 129, 130,
        135, 138, 143, 156,  86, 149, 153, 157, 161, 164,
         15,  19,  57,  70, 148,
    };
    inline constexpr uint8_t kMachineMoves2[57] = {
        223,  29, 174, 205,  46,  92, 192, 249, 244, 237,
        241, 230, 173,  59,  63, 196, 182, 240, 202, 203,
        218,  76, 231, 225,  87,  89, 216,  91,  94, 247,
        189, 104,   8, 207, 214, 188, 201, 126, 129, 111,
          9, 138, 197, 156, 213, 168, 211,   7, 210, 171,
         15,  19,  57,  70, 148, 250, 127,
    };
    inline constexpr uint8_t kTutorMoves2[3] = { 53, 85, 58 }; // Flamethrower, Thunderbolt, Ice Beam
}

#endif
